import React, { useState, useMemo } from "react";
import MatchItem from "./MatchItem";

function MatchList({ matches, selectedLeague, orderedLeagues }) {
  const [selectedDate, setSelectedDate] = useState(null);

  // 1. ВРЕМЕННО ОТКЛЮЧАЕМ ВСЕ ФИЛЬТРЫ
  const filteredMatches = useMemo(() => {
    // Просто возвращаем всё, что пришло от сервера
    console.log("RAW MATCHES IN COMPONENT:", matches);
    return matches;
  }, [matches]);

  // 2. УПРОЩЕННАЯ ГРУППИРОВКА (только по названию лиги)
  const groupedMatches = useMemo(() => {
    const groups = {};
    filteredMatches.forEach((match) => {
      const leagueName = match.league || "Другие";
      if (!groups[leagueName]) {
        groups[leagueName] = { name: leagueName, matches: [] };
      }
      groups[leagueName].matches.push(match);
    });
    return Object.entries(groups);
  }, [filteredMatches]);

  if (!matches || matches.length === 0) {
    return (
      <div className="text-center py-20 text-white">
        Сервер прислал 0 матчей. Проверь базу.
      </div>
    );
  }

  return (
    <div className="w-full">
      {/* Выводим всё подряд */}
      {groupedMatches.map(([name, group]) => (
        <div key={name} className="mb-10">
          <h2 className="text-xl font-bold text-red-500 mb-4 uppercase">
            {name}
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {group.matches.map((m) => (
              <MatchItem key={m.id} match={m} />
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

export default MatchList;
